<div class="admin-page-heading"><div><span class="admin-eyebrow">PROJECT ORGANIZATION</span><p>Create categories to organize the public project gallery.</p></div></div><section class="admin-panel category-panel"><form method="post" action="<?= e(url('/admin/categories')) ?>" class="inline-add-form"><?= csrf_field() ?><input name="name" required maxlength="120" placeholder="New category name"><button class="admin-button" type="submit">Add Category <span>＋</span></button></form><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CATEGORY</th><th>PROJECTS</th><th>SLUG</th><th></th></tr></thead><tbody><?php foreach($categories as $category): ?><tr><td><strong><?= e($category['name']) ?></strong></td><td><?= e($category['project_count']) ?></td><td><?= e($category['slug']) ?></td><td><form method="post" action="<?= e(url('/admin/categories/'.$category['id'].'/delete')) ?>" data-confirm="Remove this category? Projects will become uncategorized."><?= csrf_field() ?><button class="table-danger" type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
